action.command:
cd /workspace && docker exec -i sva-studio-postgres psql -v ON_ERROR_STOP=1 -U sva -d sva_studio <<'SQL'
GRANT USAGE ON SCHEMA graphile_worker TO sva_job_worker;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA graphile_worker TO sva_job_worker;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA graphile_worker TO sva_job_worker;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA graphile_worker TO sva_job_worker;
GRANT CONNECT ON DATABASE sva_studio TO sva_job_worker;
SQL
echo "grants applied, exit=$?"
# verify the worker role can connect and see the tables
docker exec -i sva-studio-postgres psql -U sva -d sva_studio -t -c "SELECT count(*) FROM information_schema.tables WHERE table_schema='graphile_worker';" 2>&1

